package com.ezhou.sttbutton

/** JNI entry points of libcleaner_jni (cpp/cleaner_jni.cpp). Text crosses as UTF-8 bytes. */
object LlamaNative {
    init {
        System.loadLibrary("cleaner_jni")
    }

    external fun load(path: String, threads: Int): Long
    external fun countTokens(handle: Long, text: ByteArray): Int

    /**
     * The generated bytes, or null when [cancel] was called or the prompt does not fit. The prompt is [head],
     * [text] and [tail]: the two ends are tokenized with their special tokens, [text] as plain text.
     */
    external fun clean(handle: Long, head: ByteArray, text: ByteArray, tail: ByteArray, maxTokens: Int): ByteArray?
    external fun cancel(handle: Long)

    /** Output tokens, drafted tokens, accepted draft tokens and threads used by the last [clean]. */
    external fun lastStats(handle: Long): IntArray
    external fun release(handle: Long)
}
